import sys

def main():
    data = sys.stdin.read().split()
    s = data[0] if data else ''
    st = []
    for ch in s:
        if st and abs(ord(st[-1]) - ord(ch)) == 1:
            st.pop()
        else:
            st.append(ch)
    print(''.join(st))

main()

